console.log('deflate L9  : ' + zlib.deflateSync(Buffer.from('hello hello hello hello'), { level: 9 }).toString('hex'));
console.log('zlib version: ' + (zlib.constants.ZLIB_VERNUM === 4897 ? '1.3.2.1' : String(zlib.constants.ZLIB_VERNUM)));
